(() => {
  const real = window.fetch.bind(window);
  window.fetch = (input, init) => {
    const url = typeof input === 'string' ? input : input.url;
    if (/\/api\/tts\/voices(\?|$)/.test(url)) return Promise.resolve(new Response(JSON.stringify({ error: 'The voice server did not answer.' }), { status: 503, headers: { 'content-type': 'application/json' } }));
    return real(input, init);
  };
  return true;
})()
